#!/bin/bash
set -e
name=ssw
_name=spread-sheet-widget
get_version() {
	local git_ver=$(timeout 5 git ls-remote --tags --refs https://salsa.debian.org/beckmanf/spread-sheet-widget.git | grep "refs/tags/upstream/[0-9.]+" -oE | cut -d '/' -f 4 | sort -V | tail -n 1)
	local inst_ver=$(pkgver $name)
	local arch_ver=$(aurver $_name)
	ver_check "$git_ver" "$inst_ver" "$arch_ver" && return
	local up_ver=$(wget -cqO- -T 5 -t 1 https://salsa.debian.org/beckmanf/spread-sheet-widget/-/tags | grep "upstream/[0-9.]+" -oE | cut -d '/' -f 2 | sort -V | tail -n 1)
	ver_check "$up_ver" "$inst_ver" "$arch_ver" && return
	fver "$name" "$inst_ver"
}
homepage=""
description="GTK+ library for viewing/manipulating 2D tabular data."
version=$(get_version)
depends=(acl alsa-lib appstream arpack aspell at-spi2-core attica attr avahi avogadrolibs babl baloo binutils blas-lapack-git bluez bluez-qt boost breeze-icons brotli bzip2 cairo cdparanoia colord coordgen cracklib cryptsetup curl cxx-rust-cssparser cyrus-sasl dav1d dbus dconf discount djvulibre dolphin double-conversion duktape e2fsprogs ebook-tools eigen elfutils enchant eog evince exempi exiv2 expat fdk-aac ffmpeg fftw flac flatpak fltk fontconfig frameworkintegration freetype fribidi gcc gcr3 gcr4 gdbm gdk-pixbuf gegl geocode-glib gettext gexiv2 ghostscript giflib gimp gjs gl2ps glew glib2 glibmm24 glpk glu gmp gnome-desktop gnome-online-accounts gnome-shell gnutls gpgme gpgmepp graphene graphicsmagick gsound gspell gst-plugins-bad gst-plugins-base gstreamer gtk3 gtk4 harfbuzz hdf5 highway hwloc ibus icu imagemagick inih iptables jack-git jansson java jkqtplotter-git json-c json-glib julia kactivitymanagerd karchive kauth kbookmarks kcmutils kcodecs kcolorpicker kcolorscheme kcompletion kconfig kconfigwidgets kcontacts kcoreaddons kcrash kdbusaddons kdeclarative kdecoration kdeplasma-addons kdoctools kdsoap keyutils kfilemetadata kglobalaccel kglobalacceld kguiaddons kholidays ki18n kiconthemes kidletime kio kirigami kirigami-addons kitemmodels kitemviews kjobwidgets kmod knewstuff knighttime knotifications knotifyconfig kpackage kparts kpeople kpipewire kplotting kpty kquickcharts kquickimageeditor krunner kscreenlocker kservice kstatusnotifieritem ksvg ktexteditor ktexttemplate ktextwidgets kunitconversion kuserfeedback kwallet kwayland kweathercore kwidgetsaddons kwin kwindowsystem kxmlgui lame layer-shell-qt lcms2 leptonica liba52 libaec libaio libaom libarchive libass libassuan libatasmart libavif libblockdev libbytesize libcanberra libcap libcdio libde265 libdisplay-info libdmtx libdrm libdvdnav libdvdread libei libepoxy libevdev libevent libexif libfabric libffi libfontenc libfyaml libgbm libgcrypt libgedit-amtk libgedit-gfls libgedit-gtksourceview libged